// Security headers for Cloudflare Pages Functions responses.
//
// The static `_headers` file is applied by Pages to STATIC ASSET responses only.
// It is NOT applied to responses generated by Pages Functions, so every Function
// that returns a document (admin pages, login, logout, the /p client-delivery
// pages) has to set those headers itself. The values below mirror the static
// site's `_headers` so a dynamic page carries the same protections an equivalent
// static page would.

export const SECURITY_HEADERS: Readonly<Record<string, string>> = {
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'DENY',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Strict-Transport-Security': 'max-age=31536000; includeSubDomains; preload',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
}

// Same policy as the `Content-Security-Policy` line in the static `_headers`
// file. It is applied ONLY to client-facing HTML documents whose resource model
// matches the public site (inline styles + inline scripts + Wistia/Bamboo
// embeds). Keep this string in sync with `_headers` if the policy changes.
export const CLIENT_PAGE_CSP =
  "default-src 'self'; script-src 'self' 'unsafe-inline' https://*.wistia.com https://*.wistia.net https://browser.sentry-cdn.com; style-src 'self' 'unsafe-inline'; img-src 'self' data: https://*.wistia.com https://*.wistia.net; media-src 'self' blob: https://*.wistia.com https://*.wistia.net; connect-src 'self' blob: https://videocdn.bamboo-cloud.com https://videostats.bamboo-cloud.com https://cdnapi.bamboo-cloud.com https://video.panda-os.com https://static.panda-os.com https://videostats.panda-os.com https://*.litix.io https://*.wistia.com https://*.wistia.net http://pipedream.wistia.com; font-src 'self' data: https://*.wistia.com https://*.wistia.net; object-src 'none'; frame-src 'self' https://cdn.bamboo-cloud.com https://videocdn.bamboo-cloud.com https://fast.wistia.com https://fast.wistia.net; frame-ancestors 'none'; base-uri 'self'; form-action 'self'; upgrade-insecure-requests"

// Add the missing security headers to a Function response without disturbing any
// header the route already set (cookies, redirects, content type, cache-control,
// CORS, etc.). A CSP is only attached to HTML documents when one is requested.
export function applySecurityHeaders(
  response: Response,
  options: { csp?: string } = {},
): Response {
  const headers = new Headers(response.headers)
  for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
    if (!headers.has(name)) headers.set(name, value)
  }
  if (options.csp && !headers.has('Content-Security-Policy')) {
    const contentType = headers.get('Content-Type') ?? ''
    if (contentType.toLowerCase().includes('text/html')) {
      headers.set('Content-Security-Policy', options.csp)
    }
  }
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  })
}
